<script setup>
import {computed,ref,watch} from 'vue';
import {api} from '../services/accounting.js';
import {farmCareError as farmProductionError} from '../services/farms.js';
import {transferAmounts} from '../../../shared/farm-production.js';
import FormDialog from './FormDialog.vue';
import {useAccess} from '../composables/access.js';
const {can}=useAccess();
const props=defineProps({kind:String,event:Object,lot:Object,lots:Array,farms:Array}),emit=defineEmits(['close','saved']);
const transfer=props.kind==='transfer',care=props.kind==='care',path=transfer?'feed-transfers':care?'care-costs':'deaths';
const form=ref(props.event?{...props.event}:{event_date:new Date().toLocaleDateString('sv-SE'),lot_id:props.lot?.id||'',source_lot_id:props.lot?.id||'',destination_lot_id:'',kg:'',price_per_kg:'',pigs:'',amount:'',notes:'',request_id:crypto.randomUUID()});
const sourceFarm=ref(String(props.lots.find(row=>row.id===Number(form.value.source_lot_id))?.farm_id||'')),destinationFarm=ref(String(props.lots.find(row=>row.id===Number(form.value.destination_lot_id))?.farm_id||''));
const sourceLots=computed(()=>props.lots.filter(row=>String(row.farm_id)===sourceFarm.value)),destinationLots=computed(()=>props.lots.filter(row=>String(row.farm_id)===destinationFarm.value));
const busy=ref(false),error=ref(''),removing=ref(false),sourceBalance=ref(null);let ticket=0,autoPrice='';
function lotName(row){return(props.farms.find(farm=>farm.id===row.farm_id)?.name||'Granja')+' · Lote '+row.code;}
function changeFarm(side){const rows=side==='source'?sourceLots.value:destinationLots.value;form.value[side+'_lot_id']=rows.length===1?String(rows[0].id):'';}
watch(()=>form.value.source_lot_id,async value=>{const current=++ticket;sourceBalance.value=null;if(!value||!transfer)return;const lot=props.lots.find(row=>row.id===Number(value));try{const result=await api('/farms?'+new URLSearchParams({farm_id:lot.farm_id,lot_id:value,exercise_id:'all'}));if(current!==ticket)return;sourceBalance.value=result.production;if((!form.value.price_per_kg||form.value.price_per_kg===autoPrice)&&result.production?.average_feed_price){autoPrice=result.production.average_feed_price;form.value.price_per_kg=autoPrice;}}catch{}},{immediate:true});
const total=computed(()=>{try{return Number(transferAmounts(form.value).total_amount).toLocaleString('es-ES',{style:'currency',currency:'EUR'});}catch{return '—';}});
async function save(){if(busy.value||removing.value||!can('accounting_write'))return;busy.value=true;error.value='';try{const row=form.value;await api('/farms/'+path+(row.id?'/'+row.id:''),{method:row.id?'PATCH':'POST',body:row});emit('saved',{kind:props.kind,lot_id:transfer?Number(row.source_lot_id):Number(row.lot_id)});}catch(cause){error.value=farmProductionError(cause);}finally{busy.value=false;}}
async function remove(){if(!can('accounting_write'))return;busy.value=true;error.value='';try{await api('/farms/'+path+'/'+form.value.id,{method:'DELETE',body:{version:form.value.version}});emit('saved',{kind:props.kind,lot_id:transfer?Number(form.value.source_lot_id):Number(form.value.lot_id)});}catch(cause){error.value=farmProductionError(cause);}finally{busy.value=false;}}
</script>
<template><FormDialog :title="transfer?'Traspaso de pienso':care?'Gasto de cuido':event?'Editar baja':'Registrar bajas'" :busy="busy" @close="emit('close')"><form class="event-form" @submit.prevent="save"><template v-if="!transfer"><p v-if="lot"><strong>Lote {{ lot.code }}</strong></p><label v-else for="production-lot">Granja / lote<select id="production-lot" v-model="form.lot_id" required :disabled="busy"><option value="">Selecciona granja y lote</option><option v-for="row in lots" :key="row.id" :value="row.id">{{ lotName(row) }}</option></select></label></template><label for="production-date">Fecha<input id="production-date" v-model="form.event_date" type="date" required :disabled="busy"></label><template v-if="transfer"><div class="event-columns"><label for="transfer-source-farm">Granja de origen<select id="transfer-source-farm" v-model="sourceFarm" required :disabled="busy" @change="changeFarm('source')"><option value="">Selecciona granja</option><option v-for="farm in farms" :key="farm.id" :value="String(farm.id)">{{ farm.name }}</option></select></label><label for="transfer-source-lot">Lote de origen<select id="transfer-source-lot" v-model="form.source_lot_id" required :disabled="busy"><option value="">Selecciona lote</option><option v-for="row in sourceLots" :key="row.id" :value="row.id">{{ row.code }} · {{ row.exit_date?'cerrado':'abierto' }}</option></select></label><label for="transfer-destination-farm">Granja de destino<select id="transfer-destination-farm" v-model="destinationFarm" required :disabled="busy" @change="changeFarm('destination')"><option value="">Selecciona granja</option><option v-for="farm in farms" :key="farm.id" :value="String(farm.id)">{{ farm.name }}</option></select></label><label for="transfer-destination-lot">Lote de destino<select id="transfer-destination-lot" v-model="form.destination_lot_id" required :disabled="busy"><option value="">Selecciona lote</option><option v-for="row in destinationLots" :key="row.id" :value="row.id">{{ row.code }} · {{ row.exit_date?'cerrado':'abierto' }}</option></select></label><label for="transfer-kg">Kilos de pienso<input id="transfer-kg" v-model="form.kg" inputmode="decimal" required :disabled="busy"></label><label for="transfer-price">Coste por kilo (sin IVA)<input id="transfer-price" v-model="form.price_per_kg" inputmode="decimal" required :disabled="busy"></label></div><p v-if="sourceBalance" class="muted">Pienso neto registrado en origen: {{ Number(sourceBalance.feed_net_kg).toLocaleString('es-ES') }} kg. El coste sugerido es orientativo y puedes corregirlo.</p><p><strong>Valor del traspaso: {{ total }}</strong></p></template><label v-else-if="care" for="care-amount">Importe de cuido (sin IVA)<input id="care-amount" v-model="form.amount" inputmode="decimal" placeholder="Ej. 250,00" required :disabled="busy"></label><label v-else for="death-pigs">Número de bajas<input id="death-pigs" v-model="form.pigs" type="number" min="1" max="10000000" step="1" required :disabled="busy"></label><label for="production-notes">{{ care?'Concepto / cuidador':transfer?'Notas':'Motivo / notas' }}<textarea id="production-notes" v-model="form.notes" maxlength="2000" rows="3" :disabled="busy"></textarea></label><p v-if="error" role="alert" class="notice error-notice">{{ error }}</p><div v-if="removing"><p>¿Eliminar este registro y actualizar el informe del lote?</p><div class="actions"><button type="button" class="button clear-danger" :disabled="busy||!can('accounting_write')" @click="remove">Confirmar eliminación</button><button type="button" class="button" :disabled="busy" @click="removing=false">Conservar</button></div></div><div v-else class="actions"><button class="button primary" :disabled="busy||!can('accounting_write')">Guardar</button><button v-if="event" type="button" class="button clear-danger" :disabled="busy||!can('accounting_write')" @click="removing=true">Eliminar</button></div></form></FormDialog></template>
<style scoped>.event-form{display:grid;gap:18px;margin-top:18px}.event-columns{display:grid;grid-template-columns:1fr 1fr;gap:16px}@media(max-width:600px){.event-columns{grid-template-columns:1fr}}</style>
